// API of @jinx-ui/react assumed (Table/Badge/Pagination + variant props) — verify names against the installed version.
import { useMemo, useState } from 'react';
import {
  Badge,
  Pagination,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
} from '@jinx-ui/react';

type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UserTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_VARIANT: Record<UserStatus, 'success' | 'neutral'> = {
  active: 'success',
  disabled: 'neutral',
};

export default function UserTable({ users }: UserTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
      <Table>
        <TableHead>
          <TableRow>
            <TableCell as="th">Имя</TableCell>
            <TableCell as="th">Роль</TableCell>
            <TableCell as="th">Статус</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge variant={STATUS_VARIANT[user.status]}>
                  {STATUS_LABEL[user.status]}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      <Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
    </Stack>
  );
}

